            writeInt(&buf, Int32(10))
            FfiConverterString.write(v, into: &buf)
            FfiConverterBool.write(hasTz, into: &buf)
            
        
        case let .uuid(v):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(v, into: &buf)
            
        
        case let .json(v):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(v, into: &buf)
            
        }
